WITH catalog_with_dept AS (SELECT cr.cr_reason_sk, cr.cr_returned_date_sk, cr.cr_net_loss, cp.cp_department FROM catalog_returns cr JOIN catalog_page cp ON cr.cr_catalog_page_sk = cp.cp_catalog_page_sk), store_simple AS (SELECT sr.sr_reason_sk AS cr_reason_sk, sr.sr_returned_date_sk AS cr_returned_date_sk, sr.sr_net_loss AS cr_net_loss, NULL AS cp_department FROM store_returns sr), combined_returns AS (SELECT * FROM catalog_with_dept UNION ALL SELECT * FROM store_simple), reasoned AS (SELECT crn.cr_reason_sk, r.r_reason_desc, crn.cr_returned_date_sk, crn.cp_department, SUM(crn.cr_net_loss) OVER (PARTITION BY crn.cr_reason_sk ORDER BY crn.cr_returned_date_sk ROWS UNBOUNDED PRECEDING) AS cumulative_net_loss, ROW_NUMBER() OVER (PARTITION BY crn.cr_reason_sk ORDER BY crn.cr_returned_date_sk DESC) AS rn FROM combined_returns crn JOIN reason r ON crn.cr_reason_sk = r.r_reason_sk) SELECT rr.cr_reason_sk, rr.r_reason_desc, rr.cr_returned_date_sk, rr.cp_department, rr.cumulative_net_loss, CASE WHEN rr.cumulative_net_loss > 50000 THEN 'Alert' ELSE 'OK' END AS risk_flag, rr.rn AS recent_return_rank FROM reasoned rr WHERE rr.rn = 1 ORDER BY rr.cumulative_net_loss DESC LIMIT 20
